const PRESTIGE_UPGRADES=[{id:'luckyRod',name:'Lucky Rod',icon:'<img src="assets/starter_lure.png" class="inline-icon">',desc:'+5% Luck per tier.',maxTier:3,costs:[2,3,5],bonus:l=>({luck:l*.05})},{id:'gildedScale',name:'Gilded Scale',icon:'<img src="assets/coin.png" class="inline-icon">',desc:'+4% Rupees per fish per tier. Permanent.',maxTier:3,costs:[3,4,6],bonus:l=>({rupeeBonus:l*.04})},{id:'ancientWisdom',name:'Ancient Wisdom',icon:'<img src="assets/xp.png" class="inline-icon">',desc:'+15% XP gained per tier.',maxTier:3,costs:[2,3,5],bonus:l=>({xpBonus:l*.15})},{id:'pityStone',name:'Pity Stone',icon:'<img src="assets/gem.png" class="inline-icon">',desc:'-75 pulls to guaranteed shiny per tier.',maxTier:2,costs:[4,6],bonus:l=>({shinyReduction:l*75})},{id:'anglersMark',name:"Angler's Mark",icon:'<img src="assets/icon.png" class="inline-icon">',desc:'4x offline earnings rate.',maxTier:1,costs:[5],bonus:l=>({offlineMult:l>0?4:1})}];function getPUBonus(s){let t=0;PRESTIGE_UPGRADES.forEach(u=>{let l=gameState.prestigeUpgrades[u.id]||0;if(l>0){let f=u.bonus(l);if(f[s]!=null)t+=f[s]}});return t}
