function todayStr(){return new Date(getNow()).toISOString().slice(0,10)}let spotsVisitedToday=new Set;function generateDailyQuests(){let t=todayStr();if(gameState.dailyQuestDate===t&&(gameState.dailyQuests||[]).length===3)return;spotsVisitedToday.clear();gameState.spotsVisitedToday=[];let r=parseInt(t.replace(/-/g,''))%999983,rnd=()=>{r=(r*16807)%2147483647;return(r-1)/2147483646};let p=[...QUEST_POOL].sort(()=>rnd()-.5).slice(0,3);gameState.dailyQuests=p.map(q=>{let tg=q.targets[Math.floor(rnd()*q.targets.length)];return{id:q.id,desc:q.mk(tg),type:q.type,target:tg,progress:0,mon:q.mon,rup:q.rup,done:!1}});gameState.dailyQuestDate=t}
function advanceQuest(t,a=1,e={}){if(!gameState.dailyQuests)return;let R=['Rare','Unique','Epic','Legendary','Mythical','Secret'],E=['Epic','Legendary','Mythical','Secret'];gameState.dailyQuests.forEach(q=>{if(q.done)return;let h=!1;if(q.type===t)h=!0;if(q.type==='rarePlus'&&R.includes(t))h=!0;if(q.type==='epicPlus'&&E.includes(t))h=!0;if(q.type==='legendary'&&t==='Legendary')h=!0;if(q.type==='mythical'&&t==='Mythical')h=!0;if(q.type==='rupees'&&t==='rupees'){q.progress=Math.min(q.target,(q.progress||0)+a);h=!1}if(q.type==='spots'&&t==='spots'){if(!gameState.spotsVisitedToday)gameState.spotsVisitedToday=[];let s=e.spot||'';if(!gameState.spotsVisitedToday.includes(s))gameState.spotsVisitedToday.push(s);q.progress=gameState.spotsVisitedToday.length;h=!1}if(q.type==='combo'&&t==='combo'){q.progress=Math.max(q.progress||0,a);h=!1}if(h)q.progress=Math.min(q.target,(q.progress||0)+1);if(q.progress>=q.target&&!q.done){q.done=!0;if(q.mon>0)gameState.mon+=q.mon;if(q.rup>0)gameState.rupees+=q.rup;showNotification(`[Quest] Complete! "${q.desc}" -> ${q.mon>0?'+'+q.mon+' Mon':'+'+formatNumber(q.rup)+' Rupees'}!`);updateAllUI();saveState()}})}
function getMaxInventory(){return gameState.inventoryExpanded?150:100}function crc32(s){let c=-1;for(let i=0;i<s.length;i++){let x=s.charCodeAt(i);for(let j=0;j<8;j++){c=(c>>>1)^((c^x)&1?0xEDB88320:0);x>>=1}}return(c^-1)>>>0}function computeDiscoveryHash(){return String(crc32(Object.keys(gameState.fishIndex||{}).sort().join(',')))}function checkDiscoveryHashIntegrity(){if(!gameState.discoveryHash){gameState.discoveryHash=computeDiscoveryHash();return}let l=computeDiscoveryHash();if(l!==gameState.discoveryHash){gameState.discoveryHash=l;gameState._discoveryBlocked=!0}}function updateDiscoveryHash(){gameState.discoveryHash=computeDiscoveryHash()}
const WEATHER_TYPES=[{id:'storm',label:'Storm',icon:'[Storm]',desc:'Tension drains faster | Epic+ rate +50%',tensionMult:1.5,epiPlus:.5,rupeeMult:1,shinyMult:1},{id:'mist',label:'Mist',icon:'[Mist]',desc:'Calm waters | +20% rupees',tensionMult:.7,epiPlus:0,rupeeMult:1.2,shinyMult:1},{id:'rainbow',label:'Rainbow',icon:'<img src="assets/gem.png" class="inline-icon">',desc:'Lucky skies | +8% shiny rate for 5 casts',tensionMult:.8,epiPlus:0,rupeeMult:1,shinyMult:1.08}];function tickWeatherEvent(m){if(m>0&&Math.random()<.1&&!gameState.activeWeather){let w=WEATHER_TYPES[Math.floor(Math.random()*WEATHER_TYPES.length)];gameState.activeWeather={...w,remainingCatches:5};showNotification(`${w.icon} ${w.label}! ${w.desc}`)}if(gameState.activeWeather){gameState.activeWeather.remainingCatches--;if(gameState.activeWeather.remainingCatches<=0)gameState.activeWeather=null}}function getWeatherRupeeBonus(){return gameState.activeWeather?gameState.activeWeather.rupeeMult||1:1}function getWeatherTensionMult(){return gameState.activeWeather?gameState.activeWeather.tensionMult||1:1}function getSpotStreakMultiplier(){let s=gameState.spotStreak;if(!s||s.id!==gameState.activeSpot)return 1;return Math.min(1.5,1+(s.count*.01))}function updateSpotStreak(i){if(!gameState.spotStreak)gameState.spotStreak={id:i,count:0};if(gameState.spotStreak.id===i)gameState.spotStreak.count++;else{gameState.spotStreak={id:i,count:1};showNotification('[Water] Settling in! Bonus scaling up...')}}
const JOURNAL_RECORDS=[{key:'biggestCombo',label:'Biggest combo'},{key:'rarestFishIdx',label:'Rarest fish'},{key:'mostRupeesPerCatch',label:'Best catch'},{key:'longestSessionMin',label:'Longest session'},{key:'totalPerfects',label:'Perfect catches'},{key:'longestSameRarityStreak',label:'Best streak'},{key:'mostSpeciesInSession',label:'Species in session'},{key:'totalRupeesEarned',label:'Total rupees'}];function checkJournalRecords(d,r){if(!gameState.journalUnlocked)return;let j=gameState.journal,b=!1,i=['Common','Rare','Unique','Epic','Legendary','Mythical','Secret','Triforce'].indexOf(d.rarity?d.rarity.name:'Common'),m=Math.round((getNow()-gameState._sessionStartTime)/60000);[['biggestCombo',gameState.comboCount],['rarestFishIdx',i],['mostRupeesPerCatch',r],['longestSessionMin',m],['totalPerfects',gameState.perfectHits],['longestSameRarityStreak',gameState.sameTypeCombo],['totalRupeesEarned',gameState.rupees],['mostSpeciesInSession',(gameState._sessionSpeciesSeen||[]).length]].forEach(([k,v])=>{if(v>(j[k]||0)){j[k]=v;b=!0;showNotification(`[Journal] Personal Best! ${JOURNAL_RECORDS.find(x=>x.key===k)?.label} record!`);gameState.mon+=25}});if(b)updateAllUI()}
const NPC_DIALOGUES=[{trigger:'firstRare',text:"Ahh, a fine Rare catch! The waters of Lake Hylia hold many secrets..."},{trigger:'firstLegendary',text:"A Legendary fish! I haven't seen one pulled from these waters in years..."},{trigger:'firstTriforce',text:"A Triforce Shard?! Seek them all, young one."},{trigger:'firstShiny',text:"That shimmer... a Shiny fish! They say catching one brings great fortune."},{trigger:'level10',text:"Level 10! The Frog Lure is yours."},{trigger:'level20',text:"The Sinking Lure unlocks the deep."},{trigger:'firstPrestige',text:"You've Cast Off and returned! A true master angler."},{trigger:'allCommon',text:"Every Common fish... you've catalogued them all!"},{trigger:'fullTriforce',text:"All eight shards! Link himself would be proud."}];function checkNPCTrigger(t){if(!gameState._npcUnlocked&&['firstRare','firstLegendary','firstMythical','firstShiny','firstTriforce'].includes(t))gameState._npcUnlocked=!0;if(!gameState._npcUnlocked)return;let d=NPC_DIALOGUES.find(x=>x.trigger===t),k=`_npc_${t}`;if(!d||gameState[k])return;gameState[k]=!0;showNPCDialogue(d.text);saveState()}function showNPCDialogue(t){let e=document.getElementById('npc-dialogue');if(e)e.remove();let b=document.createElement('div');b.id='npc-dialogue';b.style.cssText=`position:fixed;bottom:140px;left:50%;transform:translateX(-50%);background:#1d2232;border:3px solid #00bcd4;border-radius:10px;padding:1em 1.5em;max-width:420px;width:90%;box-sizing:border-box;z-index:3500;font-family:'Press Start 2P',monospace;font-size:0.6em;color:#e0eaff;line-height:1.8em;animation:npcSlideIn 0.4s ease-out;`;b.innerHTML=`<div style="display:flex;gap:1em;align-items:flex-start;"><div style="min-width:36px;"><img src="assets/starter_lure.png" style="width:32px;height:32px;image-rendering:pixelated;"></div><div><div style="color:#00bcd4;font-size:0.85em;margin-bottom:0.5em;">Old Man Lure</div><div>${t}</div></div></div><button onclick="this.parentElement.remove()" style="position:absolute;top:8px;right:10px;background:none;border:none;color:#ddd;cursor:pointer;font-size:1.4em;font-family:inherit;line-height:1;">[X]</button>`;document.body.appendChild(b);setTimeout(()=>{if(b.parentNode)b.remove()},9000)}
const MON_MARKET_POOL=[{id:'lucky_bait',name:'Lucky Bait',cost:25,icon:'<img src="assets/gem.png" class="inline-icon">',desc:'+15% Luck boost for 10 min',apply:()=>{gameState.temporaryBoosts.luck=Math.min(.15,(gameState.temporaryBoosts.luck||0)+.15)}},{id:'shiny_lure',name:'Shiny Lure',cost:40,icon:'<img src="assets/gem.png" class="inline-icon">',desc:'-75 pulls to next guaranteed shiny',apply:()=>{let s=gameState.activeSpot||'lake_hylia';gameState.spotPity[s]=Math.max(1,gameState.spotPity[s]-75)}},{id:'speed_scroll',name:'Speed Scroll',cost:30,icon:'<img src="assets/speed.png" class="inline-icon">',desc:'+15% Reel Power temporarily',apply:()=>{gameState.temporaryBoosts.reelSpeed=Math.min(25,(gameState.temporaryBoosts.reelSpeed||0)+15)}},{id:'combo_charm',name:'Combo Charm',cost:45,icon:'<img src="assets/speed.png" class="inline-icon">',desc:'Set your combo to 5x instantly',apply:()=>{gameState.comboCount=Math.max(gameState.comboCount,5);gameState.lastFishRarity=gameState.lastFishRarity||'Common'}},{id:'pity_stone',name:'Pity Stone',cost:55,icon:'<img src="assets/gem.png" class="inline-icon">',desc:'-100 pulls to shiny at current spot',apply:()=>{let s=gameState.activeSpot||'lake_hylia';gameState.spotPity[s]=Math.max(1,gameState.spotPity[s]-100)}},{id:'xp_elixir',name:'XP Elixir',cost:28,icon:'<img src="assets/xp.png" class="inline-icon">',desc:'+XP bonus (Scales with Level)',apply:()=>{applyXpGain(100+(gameState.level*50))}},{id:'rupee_crystal',name:'Rupee Crystal',cost:35,icon:'<img src="assets/coin.png" class="inline-icon">',desc:'+Rupee bonus (Scales with Level)',apply:()=>{let b=1000*(1+(gameState.level*.5));gameState.rupees+=Math.floor(b*getRupeeMultiplier())}}];
function refreshMonMarket(){let n=getNow(),l=gameState.lastMarketRefreshTime||0;if(n-l>86400000||!gameState.monMarketPurchaseDate){gameState.monMarketPurchased=!1;gameState.monMarketPurchaseDate=todayStr();gameState.lastMarketRefreshTime=n;gameState.monMarketItemId=Math.floor(Math.random()*MON_MARKET_POOL.length)}}function buyMonMarketItem(){refreshMonMarket();let i=MON_MARKET_POOL[gameState.monMarketItemId];if(!i||gameState.monMarketPurchased)return;if(gameState.mon<i.cost){showNotification('Not enough Mon!');return}gameState.mon-=i.cost;gameState.monMarketPurchased=!0;i.apply();showNotification(`${i.icon} ${i.name} applied!`);updateAllUI();saveState()}function getShinyCraftCost(r){return{Common:10,Rare:8,Unique:6,Epic:4,Legendary:3,Mythical:2,Secret:1,Triforce:99}[r]||10}
export function getFishByLureTier(t){let s=getActiveSpot(),p=(s.poolOverride?s.poolOverride[t]:null)||TIER_POOLS[t]||TIER_POOLS[0],l=getTotalLuck(),w=Object.entries(p).map(([n,b])=>({name:n,weight:n==='Common'?Math.max(0,b*(1-l*1.5)):b*(1+l*3)})),tot=w.reduce((a,c)=>a+c.weight,0),r=Math.random()*tot,sn=w[0].name;for(let x of w){r-=x.weight;if(r<=0){sn=x.name;break}}let rd=fishRarities.find(x=>x.name===sn)||fishRarities[0],fp=fishList[sn];if(sn==='Triforce'){let sh=fp[Math.floor(Math.random()*fp.length)];return{rarity:rd,fishName:sh.name,raw:sh}}return{rarity:rd,fishName:fp[Math.floor(Math.random()*fp.length)]}}
