function updateQuestsTab(){let c=document.getElementById('quests-list');if(!c)return;generateDailyQuests();let r=new Date();r.setHours(24,0,0,0);let ms=r-getNow(),h=Math.floor(ms/3600000),m=Math.floor((ms%3600000)/60000);c.innerHTML=`<div style="text-align:center;color:#ddd;font-size:0.68em;margin-bottom:1em;">[Daily] Quests reset in <span style="color:#ffd700;">${h}h ${m}m</span></div>`;(gameState.dailyQuests||[]).forEach(q=>{let pct=Math.min(100,Math.round((q.progress/q.target)*100)),d=q.done,div=document.createElement('div');div.className='list-item-card';div.style.borderColor=d?'#23d160':'#00bcd4';if(d)div.style.opacity='0.7';div.innerHTML=`<div class="card-content"><div style="font-size:0.85em;margin-bottom:0.5em;color:${d?'#23d160':'#fff'};">${d?'[Done] ':'[Quest] '}${q.desc}</div><div style="background:#181c24;border-radius:4px;height:8px;margin-bottom:0.4em;"><div style="height:100%;width:${pct}%;background:${d?'#23d160':'#00bcd4'};border-radius:4px;"></div></div><div style="color:#ddd;font-size:0.65em;">${q.progress}/${q.target}</div></div><div class="card-actions" style="flex-direction:column;align-items:flex-end;">${q.mon>0?`<div style="color:#a78bfa;font-size:0.75em;"><img src="assets/gem.png" style="height:12px;vertical-align:middle;"> +${q.mon}</div>`:''}${q.rup>0?`<div style="color:#ffd700;font-size:0.75em;"><img src="assets/coin.png" style="height:12px;vertical-align:middle;"> +${formatNumber(q.rup)}</div>`:''}</div>`;c.appendChild(div)})}
