function showOfflineModal(h,f,r){let o=document.createElement('div');o.style.cssText=`position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:5000;display:flex;align-items:center;justify-content:center;`;let b=document.createElement('div');b.style.cssText=`background:#1d2232;border:3px solid #00bcd4;border-radius:12px;padding:2em 2.5em;text-align:center;max-width:380px;width:90%;box-sizing:border-box;font-family:'Press Start 2P',monospace;color:#e0eaff;`;b.innerHTML=`<img src="assets/icon.png" style="width:48px;height:48px;image-rendering:pixelated;margin-bottom:0.4em;"><div style="color:#00bcd4;font-size:1em;margin-bottom:0.8em;">Welcome Back!</div><div style="color:#aaa;font-size:0.7em;margin-bottom:1.2em;line-height:1.8em;">Away for <span style="color:#ffd700;">${h} hours</span>.<br>Your rod kept working...</div><div style="background:#23283a;border-radius:8px;padding:1em;margin-bottom:1.2em;font-size:0.75em;line-height:2em;"><div><img src="assets/fish.png" class="inline-icon"> Caught: <span style="color:#23d160;">${f}</span></div><div style="display:flex;align-items:center;justify-content:center;gap:6px;"><img src="assets/coin.png" style="height:14px;"> <span style="color:#ffd700;">+${formatNumber(r)}</span></div></div><button id="offline-ok-btn" class="pixel-btn" style="padding:0.8em 2em;background:#23d160;color:#000;border-color:#17a84a;">Let's Fish!</button>`;o.appendChild(b);document.body.appendChild(o);document.getElementById('offline-ok-btn').addEventListener('click',()=>o.remove());o.addEventListener('click',e=>{if(e.target===o)o.remove()})}
function setupSettings(){let sb=document.getElementById('settings-btn'),sp=document.getElementById('settings-panel'),cb=document.getElementById('close-settings-btn');if(sb&&sp)sb.addEventListener('click',()=>sp.style.display='block');if(cb&&sp)cb.addEventListener('click',()=>sp.style.display='none');let ms=document.getElementById('music-volume'),us=document.getElementById('ui-volume'),bm=document.getElementById('bg-music');if(ms&&bm)ms.addEventListener('input',e=>{bm.volume=parseFloat(e.target.value);gameState.settings.musicVolume=parseFloat(e.target.value);saveState()});if(us)us.addEventListener('input',e=>{gameState.settings.uiVolume=parseFloat(e.target.value);saveState()});let r=document.createElement('button');r.textContent='Complete Reset';r.className='pixel-btn';r.style.cssText='background:#e74c3c;width:100%;margin-top:1em;padding:0.8em;color:#fff;text-shadow:1px 1px 0 #000;box-sizing:border-box;';r.addEventListener('click',()=>{if(confirm('Are you sure? This will delete ALL progress!')){localStorage.removeItem('zeldaFishingV2');location.reload()}});if(sp)sp.appendChild(r)}
document.addEventListener('keydown',e=>{if(e.code!=='Space')return;e.preventDefault();let a=document.querySelector('.tab-content.active');if(!a||a.id!=='fishing')return;let n=performance.now();if(n-localClickTimer<100)return;localClickTimer=n;if(fishingState.phase==='idle'&&!e.repeat)startFishing();else if(fishingState.phase==='hooking'&&!e.repeat)hookFish();else if(fishingState.phase==='reeling'){if(!fishingState.holding)fishingState.tension+=.05;fishingState.holding=!0}});document.addEventListener('keyup',e=>{if(e.code!=='Space')return;if(fishingState.phase==='reeling')fishingState.holding=!1});